<script lang="ts">
  import type { GameSettings, SaveRecord } from '$lib/domain/types';
  let { settings, saves, onUpdate, onLoad, onDelete, onBack, onTitle } = $props<{ settings: GameSettings; saves: SaveRecord[]; onUpdate: (settings: Partial<GameSettings>) => void; onLoad: (id: string) => void; onDelete: (id: string) => void; onBack: () => void; onTitle: () => void }>();
</script>
<section class="management-screen"><header class="management-header"><div><span class="eyebrow">CAPTAIN'S PREFERENCES</span><h1>설정과 항해일지</h1></div><button class="btn" onclick={onBack}>← 게임으로</button></header><div class="management-grid"><article class="panel span-6"><span class="eyebrow">AUDIO</span><h2>음향</h2>{#each [['masterVolume','전체 음량'],['musicVolume','음악'],['effectsVolume','효과음'],['ambienceVolume','환경음']] as [key, label]}<div class="field"><label for={key}>{label} · {Math.round(settings[key as keyof GameSettings] as number * 100)}%</label><input id={key} type="range" min="0" max="1" step="0.05" value={settings[key as keyof GameSettings] as number} oninput={(event) => onUpdate({ [key]: Number(event.currentTarget.value) })} /></div>{/each}</article><article class="panel span-6"><span class="eyebrow">DISPLAY & ACCESSIBILITY</span><h2>화면과 입력</h2><div class="field"><label for="quality">렌더링 품질</label><select id="quality" value={settings.quality} onchange={(event) => onUpdate({ quality: event.currentTarget.value as GameSettings['quality'] })}><option value="low">낮음</option><option value="medium">중간</option><option value="high">높음</option></select></div><label class="resource-row"><span><strong>화면 흔들림</strong><small style="display:block">대포 피격과 폭발 카메라 효과</small></span><input type="checkbox" checked={settings.screenShake} onchange={(event) => onUpdate({ screenShake: event.currentTarget.checked })} /></label><label class="resource-row"><span><strong>모션 감소</strong><small style="display:block">배경과 UI 애니메이션 최소화</small></span><input type="checkbox" checked={settings.reducedMotion} onchange={(event) => onUpdate({ reducedMotion: event.currentTarget.checked })} /></label></article><article class="panel span-12"><div class="panel-title"><div><span class="eyebrow">INDEXEDDB SAVE SLOTS</span><h2>항해일지</h2></div><button class="btn danger-button small" onclick={onTitle}>저장 후 타이틀로</button></div>{#each saves as save}<div class="save-card"><div><strong>{save.name}</strong><small class="muted" style="display:block">{save.captainName} · {save.shipName} · 본거지 {save.havenTier}단계 · {new Date(save.updatedAt).toLocaleString('ko-KR')}</small></div><div><button class="btn small" onclick={() => onLoad(save.id)}>불러오기</button> <button class="btn small danger-button" onclick={() => onDelete(save.id)}>삭제</button></div></div>{/each}</article></div></section>
